parameters.jsCode:
const body = $json.body ?? $json;
const obj = body?.data?.object ?? $json?.data?.object ?? {};
const eventType = body?.type ?? $json?.type ?? '';
if (eventType && eventType !== 'checkout.session.completed') {
  return [];
}
const emailRaw =
  obj?.customer_details?.email ||
  obj?.customer_email ||
  $json?.body?.data?.object?.customer_details?.email ||
  '';
const email = String(emailRaw).trim().toLowerCase();
if (!email || !email.includes('@')) {
  throw new Error('No customer email in Stripe payload');
}
const crypto = require('crypto');
const pem = ($env.STACKDOCK_PRIVATE_KEY_PEM || '').replace(/\\n/g, '\n');
if (!pem.includes('PRIVATE KEY')) {
  throw new Error('STACKDOCK_PRIVATE_KEY_PEM missing or invalid');
}
const payload = Buffer.from(`${email}|stackdock-pro|3macs`, 'utf8');
const signature = crypto.sign(null, payload, pem);
const b64url = signature
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/g, '');
const licenseKey = `SDOCK-${b64url}`;
return [{
  json: {
    email,
    licenseKey,
    dmgUrl: $env.STACKDOCK_DMG_URL || 'https://stackdock.iareal.net/download',
    product: 'StackDock Pro',
    macs: 3
  }
}];

